const navs=window.PREP_NAV.flatMap(g=>g.chapters);
let navOpen={},mobileMenuOpen=false;
try{const saved=JSON.parse(localStorage.getItem('hackathon-nav-groups')||'{}');if(saved&&typeof saved==='object')for(const g of window.PREP_NAV)if(typeof saved[g.id]==='boolean')navOpen[g.id]=saved[g.id]}catch(e){}
function currentGroup(key){return window.PREP_NAV.find(g=>g.chapters.some(c=>c[0]===key))||window.PREP_NAV[0]}
navOpen[currentGroup(location.hash.slice(1)||'overview').id]=true;
function navigationHTML(actual){return window.PREP_NAV.map(g=>'<details class="nav-group '+(currentGroup(actual).id===g.id?'has-current':'')+'" data-nav-group="'+g.id+'" '+(navOpen[g.id]?'open':'')+'><summary><span class="nav-group-number">'+g.number+'</span><span class="nav-group-name">'+g.title+'</span><span class="group-progress" data-group-progress="'+g.id+'"></span></summary><div class="nav-group-links">'+g.chapters.map((n,i)=>'<a href="#'+n[0]+'" '+(actual===n[0]?'class="active" aria-current="page"':'')+'><b>'+String(i+1).padStart(2,'0')+'</b><span class="nav-chapter-label">'+n[1]+'</span></a>').join('')+'</div></details>').join('')}
function bindNavigation(){document.querySelectorAll('[data-nav-group]').forEach(el=>el.ontoggle=()=>{navOpen[el.dataset.navGroup]=el.open;try{localStorage.setItem('hackathon-nav-groups',JSON.stringify(navOpen))}catch(e){}});const button=document.querySelector('[data-mobile-menu]');const paint=()=>{document.querySelector('.sidebar').classList.toggle('menu-open',mobileMenuOpen);button.setAttribute('aria-expanded',String(mobileMenuOpen));button.querySelector('span').textContent=mobileMenuOpen?'收起':'展开'};button.onclick=()=>{mobileMenuOpen=!mobileMenuOpen;paint()};document.querySelectorAll('#nav a').forEach(a=>a.addEventListener('click',()=>{mobileMenuOpen=false;paint()}));paint()}
function operationsBoardHTML(key){const group=currentGroup(key),s=Prep.groupStats(group.id),settings=Prep.getSettings(),inactive=group.onsite&&settings.deliveryMode==='online';return '<div class="operations-board"><section class="panel module-purpose"><span class="kicker">'+group.number+' / '+group.title+'</span><h2>把这一块准备到位</h2><p>'+group.intro+'</p><div class="module-links">'+group.chapters.map(c=>'<a href="#'+c[0]+'" '+(c[0]===key?'aria-current="page"':'')+'>'+c[1]+' <span aria-hidden="true">↗</span></a>').join('')+'</div></section><section class="panel module-progress" data-module="'+group.id+'"><div class="section-label"><h2>本模块筹备进度</h2><span class="badge">'+(inactive?'现场待办不计入':group.title)+'</span></div>'+Prep.deliveryHTML()+'<div class="board-metrics"><div><strong><span data-module-count="done">'+s.done+'</span><small>项</small></strong><span>已核实完成</span></div><div><strong><span data-module-count="pending">'+(s.total-s.done)+'</span><small>项</small></strong><span>仍待完成</span></div><div><strong><span data-module-count="overdue">'+s.overdue+'</span><small>项</small></strong><span>已到期 · 待补办</span></div></div><p class="caption">'+(inactive?'当前为线上活动，可先浏览参考；如设有线下集中点，请选择混合。':'待办同步到总时间轴和账户进度。切换活动形式会调整适用范围，已勾选记录保留。')+'</p></section></div>'}

let planConfig={...HackathonPlanner.defaults};
const $=s=>document.querySelector(s);
const fmt=n=>Number(n.toFixed(2)).toString();
function title(n,t,d){return `<div class="heading"><div><div class="eyebrow">PREPARATION / ${n}</div><h1>${t}</h1><p class="intro">${d}</p></div><span class="edition">建议方案 · 可按活动调整</span></div>`}
function minutesInput(key,label){const [min,max,step]=HackathonPlanner.limits[key];return `<label>${label}<span class="input-unit"><input type="number" data-plan="${key}" min="${min}" max="${max}" step="${step}" value="${planConfig[key]}" aria-label="${label}"><span>分钟</span></span></label>`}
let schemeEditing=false;
function ruleText(text){return ScoreRules.text(text,Prep.getScoring())}
function boardHTML(){const r=ScoreRules.profile(Prep.getScoring());return `<div class="chapter-board"><section class="panel scoring-preset-card"><div class="section-label"><h2>当前评分预设方案</h2><button class="text-btn" data-edit-scoring aria-expanded="${schemeEditing}" aria-controls="scoring-presets">${schemeEditing?'收起':'修改'}</button></div><div class="preset-weight"><span>专业评委</span><strong>${r.expert}<small>%</small></strong><span class="weight-plus">＋</span><span>选手互评</span><strong>${r.peer}<small>%</small></strong></div><div class="ratio"><span class="expert" style="width:${r.expert}%"></span><span class="peer" style="width:${r.peer}%"></span></div><p class="preset-formula">S = ${r.expertFactor}E + ${r.peerFactor}P</p><div id="scoring-presets" class="scoring-preset-options" ${schemeEditing?'':'hidden'} role="group" aria-label="评分方案">${ScoreRules.presets.map(value=>{const p=ScoreRules.profile(value);return `<button data-scoring-preset="${value}" aria-pressed="${value===r.expert}" class="${value===r.expert?'active':''}" ${!Prep.canConfigure()?'disabled':''}><span>专业 ${p.expert}%</span><span>选手互评 ${p.peer}%</span></button>`}).join('')}</div><p class="caption">全章节共用，规则与模板同步更新。报名开放前确定；正式发布后的变更须记录版本并通知参赛者。</p></section><div class="board-scale-column"><section class="panel board-team-card"><div class="section-label"><h2>队伍规模</h2><span class="caption">每个独立赛道</span></div><div class="board-team-controls"><label for="teamCount">预计有效提交</label><div class="input-unit"><input id="teamCount" data-plan="teams" type="number" min="6" max="120" step="1" value="${planConfig.teams}" ${!Prep.canConfigure()?'disabled':''}><span>队</span></div><div class="presets">${[20,30,31,60,120].map(n=>`<button data-teams="${n}" class="${planConfig.teams===n?'active':''}">${n}</button>`).join('')}</div></div><details class="board-timing"><summary>评审分钟数与路演增项</summary><div class="detail-body"><div class="form-grid">${minutesInput('reviewMinutes','单件专业评审')}${minutesInput('switchMinutes','每队切换与评分')}${minutesInput('openingMinutes','整场开场')}${minutesInput('closingMinutes','整场闭场')}${minutesInput('bufferMinutes','整场故障缓冲')}</div><p class="caption">演示3分钟 + 问答3分钟；每8队休息5分钟，末队后不休息。以上增项单独累加。</p></div></details></section><section class="panel board-analysis-card" aria-live="polite"><div class="section-label"><h2>队伍规模解析</h2><span class="badge" id="board-phase"></span></div><div id="board-scale-results"></div></section></div></div>`}
function updateBoard(){const p=HackathonPlanner.calculate(planConfig),target=$('#board-scale-results');if(!target)return;$('#board-phase').textContent=p.hasFinal?'海选＋决赛':'全员单轮';target.innerHTML=`<div class="board-metrics"><div><strong>${p.teams}<small>队</small></strong><span>有效提交规模</span></div><div><strong>${fmt(p.totalMinutes)}<small>分钟</small></strong><span>${p.hasFinal?'12队决赛':'全员路演'} · 含增项</span></div><div><strong>${p.reviewerCount}<small>位</small></strong><span>${p.hasFinal?'海选':'单轮'}专业评委至少</span></div></div><p class="caption">每件 ${fmt(p.reviewMinutes)} 分钟 · 另备20%评审人力${p.hasFinal?' · 决赛另配5名固定评委':''}</p>`}
function overview(){return title('01','赛制与筹备细则','先确定规则、赛道与资源，再逐项落实。30队及以下单轮，超过30队才海选至默认12队决赛。')+`<section class="panel"><div class="section-label"><h2>评审人力与路演时长</h2><span class="badge">随上方规模实时计算</span></div><div id="scaleResults" aria-live="polite"></div></section>`+Prep.dashboardHTML()+`<section class="panel dark-panel"><div class="kicker">给参赛者的底线承诺</div><h2>每件作品，都有具体反馈。</h2><p class="muted small">每个合格作品默认有3份专业评审和5份队伍互评；经授权后进入统一作品馆。名额与人力在报名开放前配齐。</p><p class="caption">未授权作品仅进受限评审目录；互评不足按全赛道预设降级。公开点赞仅用于独立人气奖。</p></section><section class="panel"><div class="section-label"><h2>赛道与奖项，先于报名确定</h2><span class="badge">当前 {{SCORE_RATIO}} 方案</span></div><p class="small muted">从零创作、二开增量分别排名；非竞争展示保留交流机会。综合奖使用{{EXPERT_PERCENT}}%专业与{{PEER_PERCENT}}%互评总分，专项奖写明对应维度，人气奖独立计算。</p><div class="actions"><a class="btn secondary" href="#tracks">赛道设置</a><a class="btn secondary" href="#awards">奖项设置</a><a class="btn secondary" href="#scoring">评分维度与公式</a></div></section><div class="note">计划和任务进度按账户保存。正式活动须冻结参数与版本，再配置报名、评审、会议和作品入口。</div>`}
function updateScale(){updateBoard();document.querySelectorAll('[data-teams]').forEach(b=>b.classList.toggle('active',+b.dataset.teams===planConfig.teams));if(!$('#scaleResults'))return;const p=HackathonPlanner.calculate(planConfig);$('#scaleResults').innerHTML=`<div class="metrics"><div class="metric"><div class="value">${p.hasFinal?'两轮':'单轮'}</div><div class="label">${p.hasFinal?'超过30队：海选 + 决赛':'30队及以下：一次正式评审'}</div></div><div class="metric"><div class="value">${p.showcaseTeams}<span>队</span></div><div class="label">${p.hasFinal?'入围决赛路演':'全部参加一次路演'}</div></div><div class="metric"><div class="value">${fmt(p.totalMinutes)}<span>分钟</span></div><div class="label">${p.hasFinal?'决赛直播总时长':'全员直播总时长'} · 含增项</div></div><div class="metric"><div class="value">${p.reviewerCount}<span>位</span></div><div class="label">${p.hasFinal?'海选专业评委最低配置':'单轮专业评委最低配置'}</div></div></div><div class="note"><strong>${p.hasFinal?'先异步看全量作品，再做决赛':'全员单轮：异步阅件 + 一次路演 + 一次锁分'}：</strong>${p.teams} 个作品 × 3 名评委 × ${fmt(p.reviewMinutes)} 分钟 ≈ ${fmt(p.reviewerHours)} 评委小时；按每位 180 分钟阅件预算，最多分配 ${p.capacity} 件，至少需 ${p.reviewerCount} 名评委，另备 20% 人力处理回避和补评。互评共 ${p.peerReviews} 份，每队约 40 分钟。${p.hasFinal?'决赛另配 5 名固定评委。':'本轮使用 3 份专业评分，不追加决赛评委或第二轮评分。'}${p.teams<8?' 6–7队遇回避时可能无法凑齐5份互评，按整赛道降级规则处理。':''}</div><div class="time-breakdown"><h3>${p.hasFinal?'决赛':'全员路演'}时长拆分</h3><dl><div><dt>演示与问答 · 基础</dt><dd>${p.showcaseTeams} × (3 + 3) = ${p.showcaseTeams*6} 分钟</dd></div><div><dt>每8队休息5分钟</dt><dd>${p.breaks} 次 × 5 = ${p.breakMinutes} 分钟</dd></div><div class="subtotal"><dt>基础小计</dt><dd>${fmt(p.baseMinutes)} 分钟</dd></div><div><dt>每队切换与评分 · 增项</dt><dd>${p.showcaseTeams} × ${fmt(p.switchMinutes)} = ${fmt(p.switchTotal)} 分钟</dd></div><div><dt>开场 / 闭场 / 故障缓冲 · 增项</dt><dd>${fmt(p.openingMinutes)} + ${fmt(p.closingMinutes)} + ${fmt(p.bufferMinutes)} 分钟</dd></div><div class="subtotal"><dt>总时长 = 基础 + 增项</dt><dd>${fmt(p.baseMinutes)} + ${fmt(p.extrasMinutes)} = ${fmt(p.totalMinutes)} 分钟</dd></div></dl></div><p class="caption">休息次数 = floor((路演队伍数 − 1) / 8)，末队后不再加休息。异步阅件人时与直播占用分开计算；互评仍按每份 8 分钟估算，不随专业评审分钟数变化。${p.totalMinutes>180?'本场超过3小时，可按原顺序分时段完成；仍属于同一轮，不自动增加决赛。':''}</p>`;document.querySelectorAll('[data-teams]').forEach(b=>b.classList.toggle('active',+b.dataset.teams===planConfig.teams))}
function bindPlanner(){
 document.querySelectorAll('[data-plan]').forEach(el=>el.addEventListener('input',()=>{try{el.setCustomValidity('');const next={...planConfig};if(el.value.trim()==='')throw Error('请填写完整参数');next[el.dataset.plan]=Number(el.value);HackathonPlanner.validate(next);planConfig=next;updateScale();Prep.planChanged()}catch(e){el.setCustomValidity(e.message);el.reportValidity()}}));
 document.querySelectorAll('[data-plan]').forEach(el=>el.addEventListener('change',()=>{if(el.checkValidity())render()}));
 document.querySelectorAll('[data-teams]').forEach(b=>b.addEventListener('click',()=>{planConfig.teams=+b.dataset.teams;Prep.planChanged();render()}));
 document.querySelector('[data-edit-scoring]')?.addEventListener('click',()=>{schemeEditing=!schemeEditing;const el=document.querySelector('#scoring-presets');el.hidden=!schemeEditing;const b=document.querySelector('[data-edit-scoring]');b.textContent=schemeEditing?'收起':'修改';b.setAttribute('aria-expanded',String(schemeEditing))});
 document.querySelectorAll('[data-scoring-preset]').forEach(b=>b.addEventListener('click',async()=>{try{await Prep.setScoring(Number(b.dataset.scoringPreset))}catch(e){toast(e.message)}}));
}
function render(){const timingOpen=document.querySelector('.board-timing')?.open;const key=location.hash.slice(1)||'overview',actual=navs.some(n=>n[0]===key)?key:'overview';$('#global-plan').innerHTML=Prep.globalHTML();$('#nav').innerHTML=navigationHTML(actual);$('#group-breadcrumb').textContent=currentGroup(actual).title;bindNavigation();$('#breadcrumb').textContent=navs.find(n=>n[0]===actual)[1];const content=actual==='overview'?overview():(window.HANDBOOK[actual]?.()||title('','内容不可用','请重新载入页面。'));$('#main').innerHTML=ruleText(Prep.chapterHTML(actual)+(currentGroup(actual).id==='rules'?boardHTML():operationsBoardHTML(actual))+'<div class="chapter-details">'+content+'</div>');document.title=`${navs.find(n=>n[0]===actual)[1]} · 筹备黑客松指北`;if(timingOpen&&document.querySelector('.board-timing'))document.querySelector('.board-timing').open=true;updateScale();bindPlanner();if(window.afterRender)window.afterRender(actual);Prep.onRendered()}
window.addEventListener('hashchange',()=>{navOpen[currentGroup(location.hash.slice(1)).id]=true;render();window.scrollTo(0,0)});render();
if(document.modelContext?.registerTool){try{const properties={};for(const [key,[min,max,step]] of Object.entries(HackathonPlanner.limits))properties[key]={type:key==='teams'?'integer':'number',minimum:min,maximum:max,multipleOf:step};Promise.resolve(document.modelContext.registerTool({name:'preview_event_scale',title:'测算黑客松规模',description:'预览队伍数、单件专业评审分钟和路演增项。30队及以下单轮，超过30队海选至12队；每8队休息5分钟。更新当前页面并保存到当前账户，不创建或发布真实活动。',inputSchema:{type:'object',properties,required:['teams'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async function(input){if(!Prep.canConfigure())throw Error('账户计划尚未加载');if(!input||typeof input!=='object'||!Object.hasOwn(input,'teams')||Object.keys(input).some(k=>!Object.hasOwn(HackathonPlanner.limits,k)))throw Error('参数不合法');const next={...planConfig,...input};HackathonPlanner.validate(next);const p=HackathonPlanner.calculate(next);planConfig=next;Prep.planChanged();if(location.hash!=='#overview')location.hash='overview';render();await Prep.flush();return {teams:p.teams,reviewMinutes:p.reviewMinutes,phase:p.hasFinal?'海选+决赛':'单轮',showcaseTeams:p.showcaseTeams,breaks:p.breaks,baseMinutes:p.baseMinutes,extrasMinutes:p.extrasMinutes,totalLiveMinutes:p.totalMinutes,minReviewers:p.reviewerCount,reviewerHours:p.reviewerHours,peerReviews:p.peerReviews,saved:Prep.isLoaded()}}})).catch(()=>{})}catch(e){}}
document.querySelector('.skip').addEventListener('click',function(e){e.preventDefault();$('#main').focus();$('#main').scrollIntoView()});

Prep.init();

if(document.modelContext?.registerTool){
 const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch(e){}};
 register({name:'configure_hackathon_schedule',title:'保存活动时间计划',description:'设置活动形式、24/48/72/96小时制作周期及北京时间开赛时刻，登录后保存至账户并更新时间轴和倒计时，不修改真实日历或任务完成状态。',inputSchema:{type:'object',properties:{durationHours:{type:'integer',enum:[24,48,72,96]},deliveryMode:{type:'string',enum:['online','onsite','hybrid']},startLocal:{type:'string',description:'YYYY-MM-DDTHH:mm（UTC+8），空字符串清除预期开赛时间'}},additionalProperties:false,minProperties:1},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||typeof input!=='object'||!Object.keys(input).length||Object.keys(input).some(k=>!['durationHours','startLocal','deliveryMode'].includes(k)))throw Error('参数不合法');return await Prep.setSchedule(input)}});
 register({name:'configure_scoring_preset',title:'切换评分预设',description:'将当前账户活动的专业/选手互评权重切换为60/40、70/30或50/50，同步规则、算例和导出模板，不改历史赛事来源和真实已发布成绩。',inputSchema:{type:'object',properties:{expertPercent:{type:'integer',enum:[60,70,50]}},required:['expertPercent'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||Object.keys(input).some(k=>k!=='expertPercent'))throw Error('参数不合法');return await Prep.setScoring(input.expertPercent)}});
 register({name:'read_preparation_tasks',title:'读取筹备任务',description:'读取当前账户已加载的任务ID、完成状态与当前赛制适用范围。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async()=>{if(!Prep.isLoaded())throw Error('账户计划尚未加载');const state=Prep.getSettings();return {durationHours:state.durationHours,startLocal:state.startLocal,deliveryMode:state.deliveryMode,tasks:Prep.tasks().map(t=>({id:t.id,chapter:t.chapter,label:t.label,completed:state.done[t.id]===true}))}}});
 register({name:'set_preparation_tasks',title:'更新筹备任务完成状态',description:'批量勾选或取消当前赛制适用的筹备任务，并保存到当前账户。仅在用户确认实际任务完成或要撤销时使用，不因为时间经过自动完成。',inputSchema:{type:'object',properties:{changes:{type:'array',minItems:1,maxItems:window.PREP_TASKS.length,items:{type:'object',properties:{id:{type:'string'},completed:{type:'boolean'}},required:['id','completed'],additionalProperties:false}}},required:['changes'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||Object.keys(input).some(k=>k!=='changes'))throw Error('参数不合法');return await Prep.setTasks(input.changes)}});
}
